```php
namespace App\Domain;

final class Decimal
{
    private const SCALE = 30;

    private function __construct(private readonly string $value)
    {
        // Normalize: strip leading zeros? bcmath handles it, and the value must already be a valid decimal string
    }

    public static function of(string|int $value): self
    {
        if (is_int($value)) $value = (string)$value;
        if (is_string($value) && preg_match('/^-?\d*(\.\d*)?$/', $value) !== 1) {
            throw new \InvalidArgumentException(sprintf('Invalid decimal literal "%s".', $value));
        }
        // Avoid "-0"
        return new self(bcadd($value, '0', self::SCALE));
    }

    public static function zero(): self { return new self('0'); }

    public function isZero(): bool { return bccomp($this->value, '0', 0) === 0; }
    public function isNegative(): bool { return str_starts_with($this->value, '-'); }

    public function add(Decimal|string $other): self
    {
        $o = is_string($other) ? self::of($other) : $other;
        return new self(bcadd($this->value, $o->value, self::SCALE));
    }

    public function sub(...)
    public function mul(Decimal|string $other): self
    {
        return new self(bcmul($this->value, $o->value, self::SCALE));
    }

    public function div(Decimal|string $other): self
    {
        return new self(bcdiv($this->value, $o->value, self::SCALE));
    }

    /** Round to the specified number of decimal places (default 6), half away from zero. */
    public function roundHalfUp(?int $places = 6): self
    {
        $places ??= 6;
        if ($places < 0 || $places > 28) throw ...;
        $neg = $this->isNegative();
        $abs = $neg ? substr($this->value, 1) : $this->value;
        $half = '0.' . str_repeat('0', $places) . '5';
        $rounded = bcadd($abs, $half, self::SCALE);
        $truncated = bcadd($rounded, '0', $places); // truncate to scale
        if (bccomp($truncated, '0', $places) === 0) { $neg = false; }
        return new self($neg ? '-'.$truncated : $truncated);
    }

    public function toScale6(): string // always format to 6 decimal places
    {
        $v = $this->roundHalfUp(6)->value;  // Hmm? toScale6 shouldn't round again…
    }
```

Careful: after roundHalfUp(6), the value has exactly 6 decimal digits (bcadd scale 6 pads with zeros: e.g., '14.262499', '8.400000'... does bcadd($x, '0', 6) always output 6 decimal digits? bcmath pads the result up to scale: bcadd('8.4', '0', 6) → '8.400000'. Yes, bcmath results are padded to the specified scale.)

