    public static function create(string $start, string $end, string $multiplier): self
    {
        if (preg_match('/^([01]?\d|2[0-3]):([0-5]\d)$/', $start) !== 1) throw InvalidWindow...
        ...
        $startMinutes = h*60+m; $endMinutes=...
        // Reject start == end (degenerate: empty or whole day? Treat as empty) — start==end → empty window
        if (bccomp($multiplier, '0', 10) < 0) throw
        return new self($startMinutes, $endMinutes, $multiplier);
    }

    public function contains(\DateTimeInterface $utcTime): bool
    {
        $t = $utcTime->format('G') * 60 + (int)$utcTime->format('i');
        // seconds → round to minute? Event ts is at second precision; window is in minute granularity.
        // E.g. 16:29:59 → 16:29 → before 16:30 → not included. 16:30:00 is included.
        // Using minute truncation is correct under the inclusive [start,end) minute semantics.
        if ($this->startMinutes < $this->endMinutes) return $t >= $start && $t < $end;
        if ($this->startMinutes === $this->endMinutes) return false;
        return $t >= $this->start || $t < $this->end;
    }

