```php
final class UsageImporter
{
    public function __construct(private readonly EntityManagerInterface $em) {}

    /** @return array{imported: int, duplicates: int} */
    public function importFile(string $path, int $batchSize = 500): array
    {
        if (!is_file($path) || !is_readable($path)) throw new ImportException("Файл не найден или недоступен: \"$path\".");
        $handle = fopen($path, 'rb');
        if ($handle === false) throw new ImportException(...);

        $rows = [];
        try {
            $lineNo = 0;
            while (($line = fgets($handle)) !== false) {
                $lineNo++;
                $trimmed = trim($line);
                if ($trimmed === '') continue;
                $rows[] = self::parseLine($trimmed, $lineNo);
            }
        } finally {
            fclose($handle);
        }

        if ($rows === []) {
            return ['imported' => 0, 'duplicates' => 0];
        }

        // Provider and model ids from the directory
        $con = $this->em->getConnection();
        $providers = [];
        foreach ($con->fetchAllAssociative('SELECT id, code FROM providers') as $r) {
            $providers[(string)$r['code']] = (int)$r['id'];
        }
        $models = [];
        foreach ($con->fetchAllAssociative('SELECT m.id AS id, p.code AS provider_code, m.code AS model_code FROM models m JOIN providers p ON p.id = m.provider_id') as $r) {
            $models[$r['provider_code'].'|'.$r['model_code']] = [(int)$r['id'], (int)$providers[$r['provider_code']]];
        }

        $resolved = [];
        foreach ($rows as $row) {
            $pId = $providers[$row['provider']] ?? null;
            if ($pId === null) throw new ImportException(sprintf('Строка %d: провайдер "%s" не найден в справочнике цен.', $row['line'], $row['provider']));
            $mref = [$row['provider'].'|'.$row['model'] => true];
            $m = $models[$row['provider'].'|'.$row['model']] ?? null;
            if ($m === null) throw new ImportException(sprintf('Строка %d: модель "%s/%s" не найдена в справочнике цен.', $row['line'], $row['provider'], $row['model']));
            $resolved[] = $row + ['provider_id' => $pId, 'model_id' => (int)$m[0]];
        }

        $count = $con->transactional(function () use ($resolved, $batchSize) {
            $inserted = 0;
            foreach (array_chunk($resolved, $batchSize) as $chunk) {
                $placeholders = [];
                $params = [];
                foreach ($chunk as $row) {
                    $placeholders[] = '(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)';
                    $params = array_merge($params, [
                        $row['provider_id'], $row['provider_request_id'], $row['model_id'], $row['user'],
                        $row['ts'], $row['tokens_input'], $row['tokens_output'], $row['tokens_cache_read'], $row['tokens_cache_write'],
                        EventStatus::Pending->value, $row['now'],
                    ]);
                }
                $sql = 'INSERT INTO usage_events '
                    . '(provider_id, provider_request_id, model_id, "user", ts, tokens_input, tokens_output, tokens_cache_read, tokens_cache_write, status, created_at) '
                    . 'VALUES ' . implode(', ', $placeholders) . ' '
                    . 'ON CONFLICT (provider_id, provider_request_id) DO NOTHING';
                $inserted += $con->executeStatement($sql, $params);
            }
            return $inserted;
        });

        return ['imported' => $count, 'duplicates' => count($resolved) - $count];
    }

    private static function parseLine(string $line, int $lineNo): array
    {
        /** @var mixed $data */
        try {
            $data = json_decode($line, true, 512, JSON_THROW_ON_ERROR);
        } catch (JsonException $e) {
            throw new ImportException(sprintf('Строка %d: некорректный JSON (%s).', $lineNo, $e->getMessage()), 0, $e);
        }
        if (!is_array($data)) throw new ImportException(sprintf('Строка %d: ожидаем JSON-объект.', $lineNo));

        $provider = self::str($data, 'provider', $lineNo);
        $providerRequestId = self::str($data, 'provider_request_id', $lineNo);
        $model = self::str($data, 'model', $lineNo);
        $user = self::str($data, 'user', $lineNo);
        $tsRaw = self::str($data, 'ts', $lineNo);
        $ts = DateTimeUtc::parse($tsRaw);

        $tokens = [];
        foreach (['tokens_input', 'tokens_output', 'tokens_cache_read', 'tokens_cache_write'] as $field) {
            $v = $data[$field] ?? null;
            if (!is_int($v) || $v < 0) {
                throw new ImportException(sprintf('Строка %d: поле "%s" должно быть целым числом >= 0.', $lineNo, $field));
            }
            $tokens[$field] = $v;
        }

        return [
            'line' => $lineNo,
            'provider' => $provider,
            'provider_request_id' => $providerRequestId,
            'model' => $model,
            'user' => $user,
            'ts' => $ts,
            'tokens_input' => $tokens['tokens_input'],
            'tokens_output' => $tokens['tokens_output'],
            'tokens_cache_read' => $tokens['tokens_cache_read'],
            'tokens_cache_write' => $tokens['tokens_cache_write'],
            'now' => (new DateTimeImmutable())->setTimezone(new DateTimeZone('UTC')),
        ];
    }

    private static function str(array $data, string $key, int $lineNo): string
    {
        $v = $data[$key] ?? null;
        if (!is_string($v) || $v === '' || preg_match('/^[ -~]+$/', $v) !== 1) {
            throw new ImportException(sprintf('Строка %d: поле "%s" должно быть непустой строкой.', $lineNo, $key));
        }
        return $v;
    }
}
```
