final class CostCalculator
{
    private const ONE_MILLION = '1000000';

    public function priceCost(PriceRow $row, TokenUsage $usage, ?OffPeakWindow $window): Decimal
    {
        $base = match ($row->getUnit()) {
            Unit::Per1mTokens => $this->perToken($row, $usage),
            Unit::Per1mTokensUnified => Decimal::of($usage->total())
                ->mul(Decimal::of((string)$row->getAnyRate()))
                ->div(self::ONE_MILLION),
        };

        if ($window !== null) {
            $base = $base->mul($window->multiplier());
        }

        return $base;
    }

    private function perToken(PriceRow $row, TokenUsage $usage): Decimal
    {
        return Decimal::zero()
            ->add(Decimal::of($usage->input)->mul((string)$row->getInputRate())->div(self::ONE_MILLION))
            ->add(Decimal::of($usage->output)->mul((string)$row->getOutputRate())->div(self::ONE_MILLION))
            ->add(Decimal::of($usage->cacheRead)->mul((string)$row->getCacheReadRate())->div(self::ONE_MILLION))
            ->add(Decimal::of($usage->cacheWrite)->mul((string)$row->getCacheWriteRate())->div(self::ONE_MILLION));
    }
}
