**ReportCsv**:

```php
final class ReportCsv
{
    public const HEADER = 'user,model,tokens_input,tokens_output,tokens_cache_read,tokens_cache_write,cost_usd';

    public static function render(array $groups, array $total): string
    {
        $lines = [self::HEADER];
        foreach ($groups as $g) {
            $lines[] = implode(',', [
                self::esc($g['user']),
                self::esc($g['model']),
                self::int6($g['tokens_input']),
                self::int6($g['tokens_output']),
                self::int6($g['tokens_cache_read']),
                self::int6($g['tokens_cache_write']),
                Decimal::of($g['cost'])->format(6),
            ]);
        }
        $lines[] = 'TOTAL,,' . implode(',', [
            self::int6($total['tokens_input']), ... , Decimal::of($total['cost'])->format(6),
        ]);
        return implode("\n", $lines) . "\n";
    }

    private static function int6(string $value): string
    {
        // integer without separators (from a possibly decimal sum)
        $v = bcadd($value, '0', 6); // ensure a valid decimal
        $parts = explode('.', $v);
        $int = ltrim($parts[0], '0');
        return $int === '' ? '0' : $int;
    }

    private static function esc(string $field): string
    {
        if (preg_match('/^[^",\r\n]*$/', $field) === 1) return $field;
        return '"' . str_replace('"', '""', $field) . '"';
    }
}
