public function report(?DateTimeImmutable $from = null, ?DateTimeImmutable $to = null): array
{
    $where = ['u.status = :status'];
    $params = ['status' => EventStatus::Rated->value];
    if ($from !== null) {
        $where[] = 'u.ts >= :from';
        $params['from'] = $from;
    }
    if ($to !== null) {
        $where[] = 'u.ts < :to';
